js=r'''
var RYAD=[1.5,2.5,4,6,10,16,25,35,50,70,95,120,150,185,240];
var GEN={cu:'меди',al:'алюминия',fe:'стали'};
function up(x){for(var i=0;i<RYAD.length;i++){if(RYAD[i]>=x*(1-1e-12))return RYAD[i];}return 0;}
function gt(a,b){return a>b*(1+1e-12);}
function mm(x,met){return fmt(x,4)+' мм²'+(met?' '+GEN[met]:'');}
function fx(x,lim){if(Math.abs(x-lim)<=Math.abs(lim)*1e-12)return fmt(x,4);for(var p=4;p<=12;p++){var r=Number(x.toPrecision(p));if(x<lim?r<lim:r>lim)return fmt(x,p);}return fmt(x,12);}
function ryad(x){var r=up(x);return r?mm(r):'свыше 240 мм² — вне стандартного ряда';}
function sync(){var m=S('sys');hideF('smax',m!=='osn');hideF('s1',m==='osn');hideF('s2',m!=='dop2');hideF('lay',m==='osn');}
function init(){$('sys').addEventListener('change',sync);sync();}
function calc(){
var m=S('sys'),osn=m==='osn',mpe=S('mpe'),mb=S('mb'),same=mpe===mb,base,h;
if(osn){var smax=P('smax');
 if(isNaN(smax))return err('Введите наибольшее сечение защитного проводника электроустановки.');
 if(smax<=0)return err('Сечение должно быть больше нуля.');
 base=smax/2;h=row('Половина наибольшего PE (ПУЭ 1.7.137)',fx(base,25)+' мм² '+GEN[mpe]);}
else{var s1=P('s1'),s2=m==='dop2'?P('s2'):s1;
 if(isNaN(s1)||isNaN(s2))return err(m==='dop2'?'Введите сечения PE обеих открытых проводящих частей.':'Введите сечение PE открытой проводящей части.');
 if(s1<=0||s2<=0)return err('Сечение должно быть больше нуля.');
 base=m==='dop2'?Math.min(s1,s2):s1/2;
 h=row(m==='dop2'?'Меньшее из сечений PE (ПУЭ 1.7.138)':'Половина сечения PE открытой части (ПУЭ 1.7.138)',mm(base,mpe));}
if(!isFinite(base))return err('Значения слишком велики для надёжного расчёта.');
var lay=S('lay'),fl,flRow,pt=osn?'1.7.137':'1.7.138',cap=osn&&gt(base,25),st,n;
if(osn){fl={cu:6,al:16,fe:50}[mb];flRow=row('Минимум в любом случае (ПУЭ 1.7.137)',mm(fl,mb));}
else if(lay==='cab'){fl=0;flRow=row('Минимум для проводника вне кабеля (ПУЭ 1.7.127)','не применяется: проводник в составе кабеля');}
else{fl=mb==='al'?16:(mb==='cu'?(lay==='mz'?2.5:4):0);
 flRow=row('Минимум для проводника вне кабеля (ПУЭ 1.7.127)',mb==='fe'?'для стали отдельно не задан':mm(fl,mb));}
n=osn?'ПУЭ 1.7.137: сечение проводников основной системы — не менее половины наибольшего сечения защитного проводника электроустановки, если оно при этом не превышает 25 мм² по меди или равноценное ему из других материалов; проводники большего сечения, как правило, не требуются; в любом случае — не менее 6 мм² меди, 16 мм² алюминия, 50 мм² стали. ':'ПУЭ 1.7.138: между двумя открытыми проводящими частями — не менее сечения меньшего из подключённых к ним PE, между открытой и сторонней — не менее половины PE открытой части; проводник вне кабеля — не тоньше минимумов 1.7.127. ';
if(same&&!(mb==='al'&&cap)){
 var eff=cap?25:base,req=Math.max(eff,fl),r=up(req),why=[];
 if(osn)h+=row(mb==='cu'?'Предел «не более 25 мм² по меди»':'Предел «25 мм² по меди или равноценное»',cap?'достигнут: больше 25 мм², как правило, не требуется':(mb==='cu'?'не достигнут':'не достигнут: алюминий проводит хуже меди, и равноценное сечение больше 25 мм²'));
 if(eff>=req*(1-1e-12))why.push(cap?'предел 25 мм² по меди':(osn?'половина наибольшего PE':(m==='dop2'?'меньший из PE':'половина PE открытой части')));
 if(fl>=req*(1-1e-12))why.push(osn?'минимум в любом случае':'минимум 1.7.127');
 h+=flRow+row('Определяющее условие',why.join(', '))+row('Минимальное сечение',mm(req,mb))+row('Принять по стандартному ряду',ryad(req));
 st='Минимум по ПУЭ '+pt+': '+mm(req,mb)+(r?(r!==req?' (по ряду — '+mm(r)+')':''):', вне стандартного ряда');
 if(cap)n+='Слова «как правило» оставляют проекту право потребовать больше 25 мм² в обоснованных случаях. ';
}else if(same){
 h+=row('Предел «25 мм² по меди или равноценное»','не применён: равноценное сечение алюминия ПУЭ не задаёт')+flRow+row('С запасом, без предела',mm(base,'al')+'; по ряду — '+ryad(base));
 st='Недостаточно данных: равноценное 25 мм² меди сечение алюминия ПУЭ не задаёт; с запасом — '+ryad(base)+' алюминия';
 n+='Алюминий проводит хуже меди, поэтому равноценное 25 мм² меди сечение больше 25 мм², но насколько — ПУЭ не говорит. Предел не применён, значение дано с запасом. ';
}else if(mpe==='al'&&mb==='cu'){
 var safe=Math.max(osn?Math.min(base,25):base,fl);
 h+=flRow+row('С запасом: то же сечение из меди',mm(safe,'cu')+'; по ряду — '+ryad(safe));
 st='Недостаточно данных: PE алюминиевый, проводник медный — точный минимум требует пересчёта по проводимости; с запасом — '+ryad(safe)+' меди';
 n+='ПУЭ 1.7.126 требует для защитных проводников из других материалов эквивалентности по проводимости. Медь проводит лучше алюминия, поэтому то же сечение из меди заведомо не хуже требуемого — это значение с запасом. ';
}else{
 var need=osn&&mpe==='cu'?Math.min(base,25):base;
 h+=flRow+row('По проводимости — не меньше, чем',mm(need,mpe)+(osn&&mpe==='al'&&cap?' (без предела 25 мм² по меди — с запасом)':''));
 st='Недостаточно данных: '+(mb==='fe'?'проводник уравнивания стальной, PE из '+GEN[mpe]:'PE медный, проводник уравнивания алюминиевый')+' — сечение пересчитывают по проводимости, а удельное сопротивление конкретного проводника калькулятору не известно';
 n+='ПУЭ 1.7.126 требует для защитных проводников из других материалов эквивалентности по проводимости; для пересчёта нужны удельные сопротивления конкретных проводников, у стали оно зависит от марки. Поэтому точный минимум калькулятор не выдаёт. ';
}
n+='Термическая стойкость к току КЗ этим правилом не проверяется.';
out(h+row('Статус',st)+note(n));
}
''',
about="""<div class="formula">Основная система (ПУЭ 1.7.137): S ≥ max( min(S<sub>PE наиб</sub> / 2; 25 мм² Cu); 6 мм² Cu / 16 мм² Al / 50 мм² Fe )<br>Дополнительная (ПУЭ 1.7.138): две открытые части — S ≥ min(S<sub>PE1</sub>; S<sub>PE2</sub>); открытая и сторонняя — S ≥ S<sub>PE</sub> / 2<br>Вне кабеля (ПУЭ 1.7.127): не менее 2,5 мм² с механической защитой и 4 мм² без неё, алюминий — не менее 16 мм²</div>
<p><b>Основная система.</b> ПУЭ 1.7.137: сечение проводников основной системы уравнивания потенциалов должно быть не менее половины наибольшего сечения защитного проводника электроустановки, если сечение проводника уравнивания потенциалов при этом не превышает 25 мм² по меди или равноценное ему из других материалов. Применение проводников большего сечения, как правило, не требуется. В любом случае сечение — не менее 6 мм² для меди, 16 мм² для алюминия и 50 мм² для стали. Наибольший защитный проводник обычно принадлежит питающей линии вводного щита; его сечение по фазной жиле определяет <a href="sechenie-pe-provodnika.html">калькулятор сечения PE</a>.</p>
<p><b>Дополнительная система.</b> ПУЭ 1.7.138: при соединении двух открытых проводящих частей — не менее сечения меньшего из защитных проводников, подключённых к этим частям; при соединении открытой и сторонней проводящей части — не менее половины сечения защитного проводника, подключённого к открытой части. Проводники, не входящие в состав кабеля, должны соответствовать 1.7.127: не менее 2,5 мм² при наличии механической защиты и 4 мм² при её отсутствии; отдельно проложенные алюминиевые — не менее 16 мм². Минимумы 2,5 и 4 мм² калькулятор применяет к меди, 16 мм² — к алюминию.</p>
<table class="t"><tr><th>Наибольший PE, медь</th><th>Половина</th><th>Минимум по ПУЭ 1.7.137</th><th>По стандартному ряду</th></tr>
<tr><td>10 мм²</td><td>5 мм²</td><td>6 мм² — минимум в любом случае</td><td>6 мм²</td></tr>
<tr><td>16 мм²</td><td>8 мм²</td><td>8 мм²</td><td>10 мм²</td></tr>
<tr><td>35 мм²</td><td>17,5 мм²</td><td>17,5 мм²</td><td>25 мм²</td></tr>
<tr><td>95 мм²</td><td>47,5 мм²</td><td>25 мм² — больше, как правило, не требуется</td><td>25 мм²</td></tr></table>
<p><b>Другой металл.</b> Как считать «равноценное» 25 мм² меди сечение, ПУЭ 1.7.137 не говорит. Для защитных проводников из других материалов ПУЭ 1.7.126 требует эквивалентности по проводимости, и ГОСТ Р 50571.5.54 формулирует требования к дополнительному уравниванию тоже через проводимость. Но для пересчёта нужно удельное сопротивление конкретного проводника, а у стали оно заметно зависит от марки. Поэтому калькулятор металлы не пересчитывает: если PE и проводник уравнивания из разных металлов или проводник стальной, он показывает требование в металле PE и минимум для выбранного металла, а статус — «Недостаточно данных». Опирается он только на очевидное: алюминий и сталь проводят хуже меди. Отсюда два значения «с запасом»: если PE алюминиевый, а проводник уравнивания медный, достаточно того же сечения из меди; если оба алюминиевые, а половина наибольшего PE больше 25 мм², калькулятор не применяет предел, раз равноценное 25 мм² меди сечение алюминия не определено. Для сравнения: руководство Schneider Electric принимает для основной системы ту же половину наибольшего PE, но ограничивает её 25 мм² меди или 35 мм² алюминия и требует не меньше 6 мм² меди или 10 мм² алюминия, — это практика руководства Schneider Electric, а не ПУЭ.</p>
<p><b>ПУЭ и ГОСТ Р 50571.5.54.</b> Расчёт ведётся по ПУЭ 7-го издания. ГОСТ Р 50571.5.54-2013 (МЭК 60364-5-54:2011) в п. 544.1.1 задаёт для проводников, присоединяемых к главной заземляющей шине, те же минимумы — 6 мм² меди, 16 мм² алюминия, 50 мм² стали — и оговаривает, что больше 25 мм² меди или эквивалентного сечения не требуется. Есть ли в этом пункте правило «не менее половины наибольшего защитного проводника», по поисковой выдаче однозначно установить не удалось: пересказы текста противоречат друг другу, а дословно пункт не виден. Если правила там нет, ГОСТ мягче ПУЭ; если есть — совпадает с ним. В обоих случаях минимум по ПУЭ не меньше. Для дополнительной системы ГОСТ (п. 544.2) требует проводимости не меньше, чем у меньшего PE или у PE половинного сечения; для проводников из одного металла это то же, что сечения по ПУЭ 1.7.138. Выпущена и редакция ГОСТ Р 50571.5.54-2024 на основе МЭК 60364-5-54:2021; её п. 544.1.1 дословно сверить тоже не удалось.</p>""",
example="""<p>Частный дом, наибольший защитный проводник — медный PE 16 мм² питающей линии вводного щита. Половина — 8 мм²: это больше минимума 6 мм² и меньше 25 мм². Проводник основной системы от главной заземляющей шины к водопроводу и газовой трубе — не менее <b>8 мм²</b> меди, по стандартному ряду — <b>10 мм²</b>.</p>
<p>В ванной корпус стиральной машины с PE 2,5 мм² соединяют со стальной ванной — сторонней проводящей частью. Половина PE — 1,25 мм², но отдельный проводник без механической защиты по ПУЭ 1.7.127 не может быть тоньше <b>4 мм²</b> меди; в защитной трубе — не тоньше 2,5 мм². Если соединяются два корпуса с PE 2,5 и 4 мм², проводник в составе кабеля должен быть не меньше меньшего из них — <b>2,5 мм²</b>.</p>""",
faqs=[
 ("Почему для основной системы не требуется больше 25 мм²?",
  "ПУЭ 1.7.137 требует половину наибольшего сечения защитного проводника, пока она не превышает 25 мм² по меди или равноценное сечение из другого металла, и оговаривает, что проводники большего сечения, как правило, не требуются. Слова «как правило» оставляют проекту право потребовать больше в обоснованных случаях."),
 ("Можно ли выполнить уравнивание стальной полосой?",
  "Можно, но для основной системы не тоньше 50 мм² стали по ПУЭ 1.7.137. Кроме того, по проводимости сталь должна быть не хуже требуемого сечения PE: ПУЭ 1.7.126 требует для защитных проводников из других материалов эквивалентности по проводимости. Удельное сопротивление стали зависит от марки, поэтому такой пересчёт калькулятор не выполняет и выводит «Недостаточно данных»."),
 ("Какой защитный проводник считать наибольшим?",
  "Наибольший из защитных проводников электроустановки — как правило, PE питающей линии вводного щита, у остальных линий сечения меньше. Если он ещё не выбран, его подбирают по сечению фазной жилы по ПУЭ 1.7.126 и таблице 1.7.5."),
 ("Совпадают ли требования ПУЭ и ГОСТ Р 50571.5.54?",
  "Минимумы 6 мм² меди, 16 мм² алюминия и 50 мм² стали и предел 25 мм² меди совпадают. Есть ли в ГОСТ Р 50571.5.54-2013 правило половины наибольшего защитного проводника, по доступным фрагментам текста однозначно установить не удалось; калькулятор считает по ПУЭ, и его минимум в любом случае не меньше."),
],
