js=r'''
var K=Math.sqrt(3)/2,RE=[1,-0.5,-0.5],IM=[0,-K,K],PH=['A','B','C'];
function gt(a,b){return a>b*(1+1e-12);}
function fx(x,lim){if(Math.abs(x-lim)<=Math.abs(lim)*1e-12)return fmt(x,4);for(var p=4;p<=12;p++){var r=Number(x.toPrecision(p));if(x<lim?r<lim:r>lim)return fmt(x,p);}return fmt(x,12);}
function sync(){var one=S('set')==='1',rz=S('put')==='rz';hideF('pa',one);hideF('pb',one);hideF('pc',one);hideF('p1',!one);hideF('rp',!rz);hideF('r0',!rz);}
function init(){$('set').addEventListener('change',sync);$('put').addEventListener('change',sync);sync();}
function pw(id,name){var raw=String($(id).value).trim();if(raw==='')return 0;var v=P(id);
 if(isNaN(v))return name+': введите число или оставьте поле пустым.';if(v<0)return name+': мощность не может быть отрицательной.';return v;}
function pct(x,u0){return fmt(100*x/u0,4)+' % U₀';}
function dev(x,u0){var d=100*(x/u0-1);if(Math.abs(d)<1e-9)d=0;return (d>0?'+':(d<0?'−':''))+fmt(Math.abs(d),4)+' %';}
function calc(){
var one=S('set')==='1',rz=S('put')==='rz',u0=P('u0'),k;
if(isNaN(u0))return err('Введите номинальное фазное напряжение U₀.');
if(u0<=0)return err('Напряжение должно быть больше нуля.');
if(gt(u0,one?1000:1000/Math.sqrt(3)))return err(one?'Калькулятор рассчитан на электроустановки до 1 кВ: U₀ не больше 1000 В.':'Калькулятор рассчитан на электроустановки до 1 кВ: в трёхфазной сети линейное напряжение √3·U₀ не больше 1000 В, то есть U₀ не больше 577 В.');
var ids=one?['p1']:['pa','pb','pc'],nm=one?['Нагрузка абонента']:['Фаза A','Фаза B','Фаза C'],p=[0,0,0];
for(k=0;k<ids.length;k++){var v=pw(ids[k],nm[k]);if(typeof v==='string')return err(v);p[k]=v;}
if(!(p[0]+p[1]+p[2]>0))return err(one?'Введите мощность нагрузки абонента.':'Введите мощность нагрузки хотя бы одной фазы.');
var rp=0,r0=0,yn=0;
if(rz){rp=P('rp');r0=P('r0');
 if(isNaN(rp)||isNaN(r0))return err('Введите сопротивление повторного заземления и заземления нейтрали источника.');
 if(rp<=0)return err('Сопротивление повторного заземления должно быть больше нуля.');
 if(r0<0)return err('Сопротивление заземления нейтрали источника не может быть отрицательным.');
 yn=1/(rp+r0);}
var y=[],sy=yn,sr=0,si=0;
for(k=0;k<3;k++){y.push(p[k]/(u0*u0));sy+=y[k];sr+=y[k]*RE[k];si+=y[k]*IM[k];}
var nr=u0*sr/sy,ni=u0*si/sy,un=Math.sqrt(nr*nr+ni*ni);
if(!isFinite(un))return err('Значения слишком велики для надёжного расчёта.');
if(un<u0*1e-9){un=0;nr=0;ni=0;}
var vv=[];for(k=0;k<3;k++){var dr=u0*RE[k]-nr,di=u0*IM[k]-ni,m=Math.sqrt(dr*dr+di*di);vv.push(m<u0*1e-9?0:m);}
var ue=rz?un*rp/(rp+r0):un,h='',st;
if(!one){
 var lo=Infinity,hi=-Infinity,nl=0;
 h+=row('Смещение нейтрали нагрузки U_N′',fmt(un,4)+' В ('+pct(un,u0)+')');
 for(k=0;k<3;k++){
  h+=row('Фаза '+PH[k]+(p[k]>0?': напряжение на нагрузке':': нагрузки нет, фаза – нейтраль нагрузки'),fmt(vv[k],4)+' В ('+pct(vv[k],u0)+')');
  if(p[k]>0){lo=Math.min(lo,vv[k]);hi=Math.max(hi,vv[k]);nl++;}}
 var same=fmt(lo,4)===fmt(hi,4);
 h+=row('Отклонение от U₀ '+(nl>1?'на нагруженных фазах':'на нагруженной фазе')+' (справочно)',same?dev(lo,u0):'от '+dev(lo,u0)+' до '+dev(hi,u0));
 h+=row('Потенциал корпусов (PE после обрыва) относительно нейтрали источника',fx(un,50)+' В');
 if(rz)h+=row('Потенциал корпусов относительно удалённой земли',fmt(ue,4)+' В')+row('Ток через повторное заземление',fmt(un/(rp+r0),4)+' А');
 st=un===0?'Оценка аварийного режима: смещения нет только при строго симметричной нагрузке':'Оценка аварийного режима: корпуса под потенциалом '+fx(un,50)+' В, '+(nl>1?'на нагруженных фазах ':'на нагруженной фазе ')+(same?fmt(lo,4)+' В':'от '+fmt(lo,4)+' до '+fmt(hi,4)+' В');
}else{
 h+=row('Ток нагрузки',fmt(vv[0]*y[0],4)+' А'+(rz?'':' — пути для тока нет'));
 h+=row('Напряжение на нагрузке',fmt(vv[0],4)+' В ('+pct(vv[0],u0)+')');
 h+=row('Потенциал N и PE абонента (корпусов) относительно нейтрали источника',fx(un,50)+' В ('+pct(un,u0)+')');
 if(rz)h+=row('Потенциал корпусов относительно удалённой земли',fmt(ue,4)+' В');
 st='Оценка аварийного режима: корпуса под потенциалом '+fx(un,50)+' В, нагрузка получает '+fmt(vv[0],4)+' В';
}
var n=one?'Однофазный абонент: ток нагрузки может вернуться к источнику только через землю. ':'Метод двух узлов: нейтраль нагрузки смещается к наиболее нагруженной фазе. ';
if(!rz)n+=one?'Без повторного заземления тока нет: приборы не работают, а N, PE и корпуса через включённую нагрузку получают фазный потенциал. ':'Повторного заземления нет: нейтраль нагрузки ничем не связана с нейтралью источника. ';
else n+='Ток через повторное заземление возвращается к источнику через землю и заземление его нейтрали, и напряжение делится между ними. ';
if(gt(un,50))n+='Между корпусами и металлом, связанным с исправным PEN, — соседней электроустановкой, опорой, трубами, — напряжение может достигать '+fx(un,50)+' В'+(rz?' (относительно удалённой земли — '+fmt(ue,4)+' В)':'')+', больше 50 В: ПУЭ 1.7.53 требует защиты при косвенном прикосновении, если напряжение превышает 50 В переменного тока. ';
else n+='Напряжение на корпусах не выше 50 В даже относительно нейтрали источника, но безопасным это не делает: оно меняется с нагрузкой и сопротивлением заземлений, а сам режим аварийный. ';
n+='Напряжение прикосновения зависит от того, чего ещё касается человек: верхняя оценка — полное смещение нейтрали U_N′, потенциал относительно удалённой земли '+(rz?'меньше':'такой же')+'. Модель считает приборы постоянными сопротивлениями: электроника с постоянной мощностью, двигатели и пробой варисторов при перенапряжении дают другую картину. Отклонения от U₀ — справочно: ГОСТ 32144-2013 нормирует ±10 % для медленных изменений напряжения в нормальном режиме, а не для аварии.';
out(h+row('Статус',st)+note(n));
}
''',
about="""<div class="formula">U<sub>N′</sub> = (U<sub>A</sub>·Y<sub>A</sub> + U<sub>B</sub>·Y<sub>B</sub> + U<sub>C</sub>·Y<sub>C</sub>) / (Y<sub>A</sub> + Y<sub>B</sub> + Y<sub>C</sub> + Y<sub>N</sub>)<br>U<sub>A</sub> = U₀∠0°, U<sub>B</sub> = U₀∠−120°, U<sub>C</sub> = U₀∠+120°&nbsp;&nbsp;&nbsp;Y = P / U₀²&nbsp;&nbsp;&nbsp;Y<sub>N</sub> = 1 / (R<sub>п</sub> + R₀) или 0<br>Напряжение на нагрузке фазы: |U<sub>ф</sub> − U<sub>N′</sub>|&nbsp;&nbsp;&nbsp;Корпуса относительно нейтрали источника: |U<sub>N′</sub>| — верхняя оценка напряжения прикосновения; относительно удалённой земли: |U<sub>N′</sub>| · R<sub>п</sub> / (R<sub>п</sub> + R₀)</div>
<p><b>Метод.</b> После обрыва PEN нейтраль нагрузки отрывается от нейтрали источника, и её потенциал находят методом двух узлов — по теореме Миллмана: фазные напряжения, взвешенные по проводимостям нагрузок, делятся на сумму проводимостей. Y<sub>N</sub> — проводимость пути, который остался между нейтралью нагрузки и нейтралью источника: через повторное заземление у нагрузки R<sub>п</sub> и заземление нейтрали источника R₀. Если такого пути нет, Y<sub>N</sub> = 0 — полный обрыв. Нейтраль смещается к наиболее нагруженной фазе: на ней напряжение падает, на слабо нагруженных растёт вплоть до линейного.</p>
<p><b>Три контрольных случая.</b> При строго симметричной нагрузке смещения нет. При двух одинаково нагруженных фазах и полном обрыве обе нагрузки оказываются последовательно на линейном напряжении: при U₀ = 220 В каждая получает √3 · 220 / 2 ≈ 190,5 В, а нейтраль смещается на 110 В. При нагрузке только одной фазы тока нет вовсе, и нейтраль нагрузки через эту нагрузку получает полный фазный потенциал.</p>
<p><b>Корпуса в TN-C-S.</b> После точки обрыва PE соединён с нейтралью нагрузки, поэтому все открытые проводящие части, присоединённые к PE, получают потенциал смещённой нейтрали. Относительно нейтрали источника это U<sub>N′</sub>. Относительно удалённой земли при повторном заземлении — U<sub>N′</sub> · R<sub>п</sub> / (R<sub>п</sub> + R₀): ток, ушедший в землю через повторное заземление, возвращается через заземление нейтрали источника, и напряжение делится между ними. Напряжение прикосновения зависит ещё от того, чего касается человек: в зоне растекания заземлителя оно меньше потенциала относительно удалённой земли, при касании трубы или конструкции, связанной с удалённой землёй, — близко к нему, а при касании металла, связанного с исправным PEN, — соседней электроустановки, опоры, труб соседей — достигает полного смещения U<sub>N′</sub>: нейтраль источника сама уходит ниже потенциала земли на ток, умноженный на R₀. Поэтому верхняя оценка — U<sub>N′</sub>, и с условным пределом 50 В калькулятор сравнивает именно её; вывода о безопасности он не делает.</p>
<p><b>Однофазный абонент.</b> Если оборвался PEN однофазного ответвления, ток нагрузки может вернуться к источнику только через землю. Без повторного заземления тока нет, приборы не работают, а N и PE абонента — и с ними корпуса — через включённую нагрузку получают потенциал, близкий к фазному. С повторным заземлением нагрузка, R<sub>п</sub> и R₀ образуют делитель. IET приводит пример: при нагрузке 7 кВт напряжение прикосновения ниже 50 В обеспечивает заземлитель 2,1 Ом; делитель 230 · 2,1 / (230² / 7000 + 2,1) даёт 50,01 В.</p>
<p><b>Допущения модели.</b> Нагрузка фазы — постоянное сопротивление R = U₀² / P при номинальном напряжении: так ведут себя нагреватели и лампы накаливания. Импульсные блоки питания и другая электроника держат мощность постоянной и при пониженном напряжении берут больший ток, двигатели при понижении тормозятся, а при повышенном напряжении пробиваются защитные варисторы приборов, и картина меняется. Сопротивление проводов и реактивная составляющая нагрузки не учитываются.</p>
<p><b>Что говорят нормы.</b> Обрыв PEN — аварийный режим, порогов для него нормы не дают. ПУЭ 1.7.145 не допускает включать коммутационные аппараты в цепь PEN; исключение — ввод однофазных ответвлений от ВЛ в индивидуальные жилые, дачные и садовые дома, где допускается одновременно отключать все проводники, если PEN разделён на PE и N до вводного аппарата. ПУЭ 1.7.102 требует повторных заземлений PEN на вводах ВЛ в электроустановки с автоматическим отключением питания, 1.7.103 ограничивает их сопротивление — каждое не более 30 Ом при линейном 380 В. ПУЭ 1.7.53 требует защиты при косвенном прикосновении, если напряжение превышает 50 В переменного тока; для потенциала корпусов это условный предел — тот же, что в ПУЭ 1.7.59 и 1.7.104, — а не граница безопасного. ГОСТ 32144-2013, п. 4.2.2, ограничивает медленные отклонения напряжения в точке передачи 10 % номинального в течение 100 % времени интервала в одну неделю; это норма качества для нормального режима, поэтому отклонения здесь показаны справочно.</p>
<p>Ток в нулевом проводе при <b>исправном</b> нуле считает <a href="tok-v-nule-perekos.html">калькулятор тока в нулевом проводе при перекосе фаз</a>, требования к самому PEN — <a href="sechenie-pen-provodnika.html">калькулятор сечения PEN-проводника</a>.</p>""",
example="""<p>Трёхфазный ввод 220/380 В, нагрузка фаз 3, 1 и 0,5 кВт, PEN оборвался, повторного заземления нет. Сопротивления нагрузок: 220² / 3000 ≈ 16,13 Ом, 48,4 Ом и 96,8 Ом. Метод двух узлов даёт смещение нейтрали <b>112 В</b>: нагруженная фаза A получает всего 112 В, фазы B и C — <b>277,6 В</b> и <b>305,3 В</b>, на 26 и 39 % выше номинального. Все корпуса, присоединённые к PE после точки обрыва, оказываются под потенциалом 112 В.</p>
<p>С повторным заземлением 30 Ом и заземлением нейтрали источника 4 Ом смещение уменьшается до 85,1 В, потенциал корпусов относительно удалённой земли — 75,09 В, фазы B и C получают 260,6 и 283,1 В. Опасность остаётся: между корпусом и металлом, связанным с исправным PEN, — до 85,1 В, больше 50 В.</p>""",
